                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_history_is_newest_first_and_only_for_that_customer(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    other = order(shop, "c2", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert [o["order_id"] for o in body["orders"]] == [second, first]
    assert other not in [o["order_id"] for o in body["orders"]]


def test_totals_match_order_summary_including_discount(shop):
    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    summary = shop.orders.handle_get(oid).body
    assert summary["discount_cents"] == 1800
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": oid, "status": "placed", "total_cents": summary["total_cents"]}
    assert entry["total_cents"] == 10200


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_sums_totals_and_excludes_cancelled(shop):
    kept = order(shop, "c2", ("LAMP", 2)).body["order_id"]   # total 10200 after gold discount
    cancelled = order(shop, "c2", ("BOOK", 1)).body["order_id"]
    order(shop, "c1", ("PEN", 1))                             # other customer, not counted
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 1, "lifetime_value_cents": 10200}
    assert shop.orders.handle_get(kept).body["total_cents"] == 10200


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, False, "3", None, 2.0):
        response = shop.insights.handle_top_customers(bad)
        assert response.status == 400
        assert "error" in response.body


def test_top_customers_ranks_by_lifetime_value_and_skips_zero(shop):
    order(shop, "c2", ("LAMP", 2))            # c2 (Grace): 10200
    order(shop, "c1", ("BOOK", 2))            # c1 (Ada): 5000
    response = shop.insights.handle_top_customers(10)
    assert response.status == 200
    assert response.body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 10200},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 5000},
    ]}


def test_top_customers_excludes_cancelled_only_customers(shop):
    oid = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    assert shop.insights.handle_top_customers(10).body == {"customers": []}


def test_top_customers_respects_limit_and_ties_by_id(shop):
    order(shop, "c2", ("PEN", 1))             # 300
    order(shop, "c1", ("PEN", 1))             # 300, tie: c1 sorts first
    body = shop.insights.handle_top_customers(10).body
    assert [c["customer_id"] for c in body["customers"]] == ["c1", "c2"]
    assert [c["customer_id"] for c in shop.insights.handle_top_customers(1).body["customers"]] == ["c1"]


